import{_ as d}from"./chunks/prontera-church.uydloSKv.js";import{c as a,Q as r,j as e,m as h}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"卡片大全","description":"RO3 全卡片效果与掉落来源指南","frontmatter":{"title":"卡片大全","description":"RO3 全卡片效果与掉落来源指南","lastUpdated":true},"headers":[],"relativePath":"database/cards.md","filePath":"database/cards.md","lastUpdated":1780230058000}'),o={name:"database/cards.md"};function l(i,t,b,n,s,c){return r(),e("div",null,[...t[0]||(t[0]=[h('<h1 id="卡片大全" tabindex="-1">卡片大全 <a class="header-anchor" href="#卡片大全" aria-label="Permalink to &quot;卡片大全&quot;">​</a></h1><p><img src="'+d+'" alt="RO3 卡片系统"></p><blockquote><p>测试服数据尚未公开，以下为基于 RO 经典设定的卡片系统介绍和推测数据。正式上线后将持续更新。</p></blockquote><h2 id="卡片系统介绍" tabindex="-1">卡片系统介绍 <a class="header-anchor" href="#卡片系统介绍" aria-label="Permalink to &quot;卡片系统介绍&quot;">​</a></h2><p>卡片是 RO 系列的经典系统，可插入装备孔位获得额外属性加成。每件装备最多可插1张卡片（部分高级装备可能有2孔）。</p><h3 id="卡片部位" tabindex="-1">卡片部位 <a class="header-anchor" href="#卡片部位" aria-label="Permalink to &quot;卡片部位&quot;">​</a></h3><table tabindex="0"><thead><tr><th>部位</th><th>可插卡装备</th><th>效果方向</th></tr></thead><tbody><tr><td>武器卡</td><td>武器</td><td>攻击增伤、属性附魔、种族增伤</td></tr><tr><td>铠甲卡</td><td>铠甲</td><td>HP增加、减伤、属性抗性</td></tr><tr><td>披肩卡</td><td>披肩</td><td>回避、减伤、属性抗性</td></tr><tr><td>鞋子卡</td><td>鞋子</td><td>HP/SP回复、移动速度、血量</td></tr><tr><td>头盔卡</td><td>头盔</td><td>属性点、SP上限、特殊效果</td></tr><tr><td>饰品卡</td><td>饰品</td><td>稀有特殊效果</td></tr></tbody></table><h3 id="卡片品质" tabindex="-1">卡片品质 <a class="header-anchor" href="#卡片品质" aria-label="Permalink to &quot;卡片品质&quot;">​</a></h3><table tabindex="0"><thead><tr><th>品质</th><th>颜色</th><th>掉落来源</th></tr></thead><tbody><tr><td>普通</td><td>白</td><td>普通怪物掉落</td></tr><tr><td>稀有</td><td>蓝</td><td>精英怪/MVP BOSS掉落</td></tr><tr><td>史诗</td><td>紫</td><td>限时活动/高难副本</td></tr><tr><td>传说</td><td>金</td><td>赛季奖励/顶级团本</td></tr></tbody></table><h2 id="已知卡片-基于经典ro推测" tabindex="-1">已知卡片（基于经典RO推测） <a class="header-anchor" href="#已知卡片-基于经典ro推测" aria-label="Permalink to &quot;已知卡片（基于经典RO推测）&quot;">​</a></h2><h3 id="武器卡片" tabindex="-1">武器卡片 <a class="header-anchor" href="#武器卡片" aria-label="Permalink to &quot;武器卡片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卡片名</th><th>品质</th><th>推测效果</th><th>掉落怪物</th></tr></thead><tbody><tr><td>白蚁卡</td><td>白</td><td>ATK +10</td><td>白蚁</td></tr><tr><td>邪骸矿工卡</td><td>蓝</td><td>暴击伤害 +25%</td><td>邪骸矿工</td></tr><tr><td>米诺斯卡</td><td>蓝</td><td>对大型怪物增伤 +15%</td><td>米诺斯</td></tr><tr><td>邪骸弓箭手卡</td><td>蓝</td><td>远程伤害 +10%</td><td>邪骸弓箭手</td></tr><tr><td>海葵卡</td><td>蓝</td><td>对人形系增伤 +20%</td><td>海葵</td></tr></tbody></table><h3 id="铠甲卡片" tabindex="-1">铠甲卡片 <a class="header-anchor" href="#铠甲卡片" aria-label="Permalink to &quot;铠甲卡片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卡片名</th><th>品质</th><th>推测效果</th><th>掉落怪物</th></tr></thead><tbody><tr><td>绿棉虫卡</td><td>白</td><td>HP +200</td><td>绿棉虫</td></tr><tr><td>大嘴鸟卡</td><td>蓝</td><td>HP +10%</td><td>大嘴鸟</td></tr><tr><td>兽人战士卡</td><td>蓝</td><td>DEF +5, HP +5%</td><td>兽人战士</td></tr><tr><td>恶魔波利卡</td><td>紫</td><td>全属性抗性 +10%</td><td>恶魔波利</td></tr></tbody></table><h3 id="披肩卡片" tabindex="-1">披肩卡片 <a class="header-anchor" href="#披肩卡片" aria-label="Permalink to &quot;披肩卡片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卡片名</th><th>品质</th><th>推测效果</th><th>掉落怪物</th></tr></thead><tbody><tr><td>波利卡</td><td>白</td><td>无属性抗性 +5%</td><td>波利</td></tr><tr><td>九尾狐卡</td><td>蓝</td><td>AGI +2, 闪避 +10</td><td>九尾狐</td></tr><tr><td>幽灵剑士卡</td><td>蓝</td><td>无属性抗性 +20%</td><td>幽灵剑士</td></tr><tr><td>天使波利卡</td><td>紫</td><td>圣属性抗性 +20%</td><td>天使波利</td></tr></tbody></table><h3 id="鞋子卡片" tabindex="-1">鞋子卡片 <a class="header-anchor" href="#鞋子卡片" aria-label="Permalink to &quot;鞋子卡片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卡片名</th><th>品质</th><th>推测效果</th><th>掉落怪物</th></tr></thead><tbody><tr><td>苍蝇卡</td><td>白</td><td>HP +100, SP +20</td><td>苍蝇</td></tr><tr><td>黑狐卡</td><td>蓝</td><td>AGI +1, HP +15%</td><td>黑狐</td></tr><tr><td>虎王卡</td><td>紫</td><td>无限移动加速</td><td>虎王(MVP)</td></tr></tbody></table><h3 id="头盔卡片" tabindex="-1">头盔卡片 <a class="header-anchor" href="#头盔卡片" aria-label="Permalink to &quot;头盔卡片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卡片名</th><th>品质</th><th>推测效果</th><th>掉落怪物</th></tr></thead><tbody><tr><td>土拨鼠卡</td><td>白</td><td>HP +100</td><td>土拨鼠</td></tr><tr><td>小恶魔卡</td><td>蓝</td><td>ATK +10</td><td>小恶魔</td></tr><tr><td>恶魔侍者卡</td><td>蓝</td><td>SP +20%</td><td>恶魔侍者</td></tr></tbody></table><h2 id="各职业卡片推荐速查" tabindex="-1">各职业卡片推荐速查 <a class="header-anchor" href="#各职业卡片推荐速查" aria-label="Permalink to &quot;各职业卡片推荐速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职业定位</th><th>武器</th><th>铠甲</th><th>披肩</th><th>鞋子</th><th>头盔</th></tr></thead><tbody><tr><td>物理输出</td><td>白蚁/邪骸矿工</td><td>大嘴鸟</td><td>九尾狐</td><td>黑狐</td><td>小恶魔</td></tr><tr><td>魔法输出</td><td>魔法攻击卡</td><td>大嘴鸟</td><td>幽灵剑士</td><td>黑狐</td><td>恶魔侍者</td></tr><tr><td>坦克</td><td>米诺斯</td><td>大嘴鸟/兽人</td><td>幽灵剑士</td><td>黑狐</td><td>土拨鼠</td></tr><tr><td>治疗</td><td>可选</td><td>大嘴鸟</td><td>可选</td><td>黑狐</td><td>恶魔侍者</td></tr><tr><td>PVP</td><td>海葵</td><td>大嘴鸟</td><td>幽灵剑士</td><td>黑狐</td><td>小恶魔</td></tr></tbody></table><h2 id="卡片搭配原则" tabindex="-1">卡片搭配原则 <a class="header-anchor" href="#卡片搭配原则" aria-label="Permalink to &quot;卡片搭配原则&quot;">​</a></h2><ol><li><strong>同类叠加</strong>：多张同类百分比卡片效果相加（如两张大嘴鸟卡 = HP+20%）</li><li><strong>属性克制</strong>：根据练级地图选择对应属性卡（如不死系地图用圣属性卡）</li><li><strong>预算优先</strong>：白卡容易获取，蓝卡需要刷精英，紫/金卡为毕业目标</li><li><strong>PVP专用</strong>：人形系增伤/减伤卡片在GVG中效果显著</li></ol>',24)])])}const q=a(o,[["render",l]]);export{m as __pageData,q as default};
